import React, { useState, useEffect, useCallback } from 'react';
import axios from 'axios';
import './ReportForm.css';

const ReportForm = ({ onReportSubmit }) => {
  const [description, setDescription] = useState('');
  const [location, setLocation] = useState('');
  const [incidentType, setIncidentType] = useState('General');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const incidentTypes = [
    'General',
    'Harassment',
    'Theft',
    'Assault',
    'Suspicious Activity',
    'Medical Emergency',
    'Fire',
    'Domestic Violence',
    'Stalking',
    'Other'
  ];

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!description.trim()) return;

    setIsSubmitting(true);
    try {
      await axios.post('/api/reports', {
        description: `[${incidentType}] ${description}`,
        location: location || 'Not specified'
      });

      // Send WhatsApp notification for incident report via native WhatsApp links (no Twilio)
      const envList = process.env.REACT_APP_EMERGENCY_CONTACTS || process.env.REACT_APP_EMERGENCY_CONTACT || '';
      const emergencyContacts = envList
        .split(',')
        .map((s) => s.trim())
        .filter(Boolean);
      if (emergencyContacts.length > 0) {
        const msg = `📝 ${incidentType.toUpperCase()} INCIDENT: ${description}. Location: ${location || 'Not specified'}. Reported via SafeHaven app.`;
        emergencyContacts.forEach((to, idx) => {
          const number = to.replace(/[^\d+]/g, '');
          const url = `https://wa.me/${encodeURIComponent(number)}?text=${encodeURIComponent(msg)}`;
          setTimeout(() => window.open(url, '_blank', 'noopener,noreferrer'), idx * 300);
        });
      }

      setDescription('');
      setLocation('');
      setIncidentType('General');
      onReportSubmit();
    } catch (error) {
      console.error('Error submitting report:', error);
    }
    setIsSubmitting(false);
  };

  const getCurrentLocation = useCallback(async () => {
    try {
      if (navigator.permissions && navigator.permissions.query) {
        const res = await navigator.permissions.query({ name: 'geolocation' });
        if (res && res.state === 'denied') {
          alert('Location permission denied. Enable it in your browser settings and reload.');
          return;
        }
      }
    } catch (_) {}

    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        async (position) => {
          const { latitude, longitude } = position.coords;
          try {
            const address = await getAddressFromCoords(latitude, longitude);
            setLocation(`${address} (${latitude.toFixed(6)}, ${longitude.toFixed(6)})`);
          } catch {
            setLocation(`${latitude.toFixed(6)}, ${longitude.toFixed(6)}`);
          }
        },
        (err) => {
          const map = {
            1: 'Location permission denied. Allow access and try again.',
            2: 'Position unavailable. Check network/GPS and try again.',
            3: 'Timeout getting position. Try again.'
          };
          alert(map[err && err.code] || 'Unable to get location');
        },
        { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
      );
    } else {
      alert('Location not supported');
    }
  }, []);

  useEffect(() => {
  }, []);

  const getAddressFromCoords = async (lat, lng) => {
    const apiKey = process.env.REACT_APP_GOOGLE_MAPS_API_KEY;
    if (!apiKey) throw new Error('No API key');

    const response = await fetch(
      `https://maps.googleapis.com/maps/api/geocode/json?latlng=${lat},${lng}&key=${apiKey}`
    );
    const data = await response.json();

    if (data.results && data.results[0]) {
      return data.results[0].formatted_address;
    }
    throw new Error('No address found');
  };

  return (
    <div className="report-form-container">
      <h2>Report Incident</h2>
      <form onSubmit={handleSubmit} className="report-form">
        <select
          value={incidentType}
          onChange={(e) => setIncidentType(e.target.value)}
          className="incident-type-select"
        >
          {incidentTypes.map(type => (
            <option key={type} value={type}>{type}</option>
          ))}
        </select>

        <textarea
          placeholder="Describe the incident..."
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          required
        />

        <div className="location-input">
          <input
            type="text"
            placeholder="Location (optional)"
            value={location}
            onChange={(e) => setLocation(e.target.value)}
          />
          <button type="button" onClick={getCurrentLocation} className="location-btn">
            📍
          </button>
        </div>

        <button type="submit" disabled={isSubmitting} className="submit-btn">
          {isSubmitting ? 'Submitting...' : 'Submit Report'}
        </button>
      </form>
    </div>
  );
};

export default ReportForm;
